            chromaticAberration: value => { chromaticPass.uniforms.uIntensity.value = value; chromaticPass.enabled = value > 0; },
            filmGrain: value => { grainPass.uniforms.uIntensity.value = value; grainPass.enabled = value > 0; },
            nebulaIntensity: value => nebulaMaterial.uniforms.uIntensity.value = value,
            lensFlareEnabled: value => lensFlarePass.enabled = value && STATE.lensFlareIntensity > 0,
            lensFlareIntensity: value => { lensFlarePass.uniforms.uIntensity.value = value; lensFlarePass.enabled = STATE.lensFlareEnabled && value > 0; },
            dofEnabled: value => customDOFPass.enabled = value,
            dofFocus: value => customDOFPass.uniforms.uFocus.value = value,
            dofFocalLength: value => customDOFPass.uniforms.uFocalLength.value = value,
